// view order received page event
// https://developers.pinterest.com/docs/tag/conversion/
// Note: Server-side transmission is handled via PHP Conversions API, this only fires the browser pixel
pmw.bus.on("pmw:pixel:purchase", (payload) => {

	try {
		if (pmw.canNotFirePinterestEvent()) return
		if (!pmw.shouldFireBrowserPixel(payload, "pinterest")) return

		// The event ID has to match the one the Conversions API sends for the same
		// order ("pmw_<order id>"), otherwise Pinterest counts the browser event
		// and the server event as two separate purchases.
		const data = {
			event_id      : payload.pixels?.pinterest?.event_id || "pmw_" + pmwDataLayer.order.id.toString(),
			value         : pmwDataLayer.order.value.marketing,
			order_quantity: pmwDataLayer.order.quantity,
			currency      : pmwDataLayer.order.currency,
			order_id      : pmwDataLayer.order.id.toString(),
			line_items    : pmw.pinterestFormattedOrderItems(),
		}

		pintrk("track", "checkout", data)
		pmw.console.log("Pinterest Pixel: checkout event sent", data)

	} catch (e) {
		console.error(e)
	}
})
